package task2;

import java.util.*; public class CachedStockProxy implements StockProvider { private static class Entry { double price; long time; Entry(double p,long t){price=p;time=t;} } private final StockProvider provider; private final long ttl; private final Map<String,Entry> cache=new HashMap<>(); public CachedStockProxy(StockProvider p,long ttl){if(p==null)throw new IllegalArgumentException();provider=p;this.ttl=ttl;} public double getMarketPrice(String ticker){String key=ticker.toUpperCase(java.util.Locale.ROOT);long now=System.currentTimeMillis();Entry e=cache.get(key);if(e!=null && now-e.time<ttl){System.out.printf("[CACHE HIT] Returning cached price for %s: $%.2f (Age: %d ms)%n",key,e.price,now-e.time);return e.price;}System.out.printf("[NETWORK FETCH] Cache miss or expired for %s. Calling upstream adapter...%n",key);double price=provider.getMarketPrice(key);cache.put(key,new Entry(price,System.currentTimeMillis()));return price;}public String getStatus(String ticker){return provider.getStatus(ticker);} }
